sed -n '1,60p' tools/ref_page.py; echo ...; python3 -c "
import json;d=json.load(open('data/verification/sources/refs_online.json'))
print(json.dumps(d['BQT'],ensure_ascii=False,indent=1))"

cd /home/sfmqrb/git/rishe/data/verification/sources/refs && python3 - <<'EOF'
import re
def leaves(p):
    return open(p,encoding='utf-8',errors='replace').read().split('\f')
v1=leaves('BQT_v1_pages.txt'); v2=leaves('BQT_v2_pages.txt')
for i in (246,247,282,283):
    print('=== v1 leaf',i,'(p~%d)'%(i-210 if i<300 else i-220),'===')
    print(v1[i][:1500])
EOF

grep -l '"Keu 4"' data/extracted/batch/*.json | head; python3 - <<'EOF'
import json,glob
for f in sorted(glob.glob('data/extracted/batch/*.json')):
    d=json.load(open(f))
    for e in d.get('entries',[]):
        r=e.get('root') or {}
        n=r.get('name','')
        if n in ('Keu 4','Karana','Ôus 1','Ger 2','Ahu','Aiw','Mew','Wek','Kwer','Ksei 2','Těu 1','Ud 1'):
            print(f, n, r.get('lang'), r.get('gloss'), r.get('refs'), r.get('redirect'))
EOF

python3 - <<'EOF'
import json
for f,names in (('data/extracted/batch/page-264.json',('Keu 4',)),('data/extracted/batch/page-354.json',None),('data/extracted/batch/page-279.json',None)):
    d=json.load(open(f))
    for e in d['entries']:
        r=e.get('root') or {}
        if r.get('name','').startswith('Keu'):
            print(f, json.dumps(r,ensure_ascii=False))
            for n in e['nodes'][:6]:
                print('   ',n['id'],n.get('lang'),n.get('refs'),[w.get('translit')+' : '+str(w.get('gloss')) for w in n['words']])
EOF

