import re
def nearby(path,lineno,win=40):
    L=open(path,encoding='utf-8',errors='replace').read().split('\n')
    lo=max(0,lineno-1-win); hi=min(len(L),lineno-1+win)
    nums=[]
    for k in range(lo,hi):
        for m in re.finditer(r'(?m)^\s*(\d{2,4})\s*$',L[k]):
            nums.append((k+1,m.group(1)))
    return nums
for ln in (4241,4247,4458,4524,5918,5989,3658):
    print('BRT line',ln,'nums',nearby('BRT.txt',ln)[:8])
def leafof(path,lineno):
    t=open(path,encoding='utf-8',errors='replace').read()
    lines=t.split('\n')
    upto='\n'.join(lines[:lineno])
    return upto.count('\f')
for ln in (4182,5037,9258):
    print('HUB line',ln,'leaf',leafof('HUB.txt',ln),'-> printed p',leafof('HUB.txt',ln)-10)
print('WLD Bd2 leaf 323 -> printed 319 (marker seen in text)')
# AHD page for 'ne. Not.'
print('AHD leaf', leafof('AHD_watkins1985.txt',774))
EOF

